function validate(input) {
  const [{ Users = [], Orders = [], Items = [] }] = input;
  const isDate = d => /^\d{4}-\d{2}-\d{2}$/.test(d);
  const users = new Set(), items = new Set(), orders = new Set(), sellerDays = new Set();
  for (const [id, joined] of Users) {
    if (id === null) return 'Every user needs a user_id.';
    if (users.has(id)) return `user_id ${id} appears twice in Users.`;
    if (joined !== null && !isDate(joined)) return `join_date ${joined} is not YYYY-MM-DD.`;
    users.add(id);
  }
  for (const [id] of Items) {
    if (id === null) return 'Every item needs an item_id.';
    if (items.has(id)) return `item_id ${id} appears twice in Items.`;
    items.add(id);
  }
  for (const [id, date, item, buyer, seller] of Orders) {
    if (id === null || date === null || item === null || buyer === null || seller === null) return 'Every column of Orders is required.';
    if (orders.has(id)) return `order_id ${id} appears twice in Orders.`;
    orders.add(id);
    if (!isDate(date)) return `order_date ${date} is not YYYY-MM-DD.`;
    if (!items.has(item)) return `Order ${id} sells item ${item}, which is not in Items.`;
    if (!users.has(buyer) || !users.has(seller)) return `Order ${id} names a user who is not in Users.`;
    const key = `${seller}|${date}`;
    if (sellerDays.has(key)) return `Seller ${seller} sold twice on ${date}.`;
    sellerDays.add(key);
  }
  return null;
}

