function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  // A small brand pool makes favorite brands match often; dates cross a year boundary.
  const brands = small ? ['Samsung', 'Lenovo', 'LG'] : ['Samsung', 'Lenovo', 'LG', 'HP', 'Apple'];
  const day = offset => new Date(Date.UTC(2019, 0, 1 + offset)).toISOString().slice(0, 10);
  const userCount = small ? pick(5) : 300, itemCount = small ? 1 + pick(4) : 200, orderCount = small ? pick(9) : 1500;
  const Users = [], Items = [], Orders = [];
  for (let u = 1; u <= userCount; u++) Users.push([u, day(pick(200)), brands[pick(brands.length)]]);
  for (let i = 1; i <= itemCount; i++) Items.push([i, brands[pick(brands.length)]]);
  // Order ids follow creation, while dates are random, so id order and date order disagree.
  const used = new Set(), span = small ? 6 : 400, start = small ? 362 : 200;
  for (let tries = 0; userCount && Orders.length < orderCount && tries < orderCount * 5; tries++) {
    const seller = 1 + pick(userCount), date = day(start + pick(span));
    if (used.has(`${seller}|${date}`)) continue;
    used.add(`${seller}|${date}`);
    Orders.push([Orders.length + 1, date, 1 + pick(itemCount), 1 + pick(userCount), seller]);
  }
  return [{ Users, Orders, Items }];
}
